function catalogueFilters106(){const rs=visibleReleases106();return `<div class="filter105 panel">${select105('filter-artist',L105('Artis','Artist'),ui105.artist||'all',[['all',L105('Semua artis','All artists')],...[...new Set(rs.map(r=>r.artist).filter(Boolean))].sort()])}${select105('filter-type',L105('Jenis rilisan','Release type'),ui105.type,[['all',L105('Semua jenis','All types')],['single','Single'],['ep','EP'],['album','Album']])}${select105('filter-status','Status',ui105.status,[['all',L105('Semua status','All statuses')],...['draft','submitted','review','revision','approved','delivered','followup','partial','live','closed','partial_closed'].filter(s=>isLabel10()||s!=='draft').map(s=>[s,status10(s)])])}${select105('filter-service',L105('Layanan','Service'),ui105.service||'all',[['all',L105('Semua layanan','All services')],'Standard','Express','MAX'])}${!isLabel10()?select105('filter-member','Label',ui105.member||'all',[['all',L105('Semua label','All labels')],...ten.members.map(m=>[m.id,m.name])]):''}${field105('filter-from',L105('Tanggal mulai','From date'),ui105.from,'date')}${field105('filter-to',L105('Tanggal akhir','To date'),ui105.to,'date')}${select105('filter-wami','WAMI',ui105.wami,[['all',L105('Semua','All')],['none',L105('Belum terdaftar','Not registered')],['partial',L105('Sebagian tercatat','Partially recorded')],['registered',L105('Terdaftar','Registered')]])}${b106(L105('Reset filter','Reset filters'),'reset','','text')}</div>`}
