const detailBase106=detail105;
detail105=function(){const html=detailBase106(),t=document.createElement('template');t.innerHTML=html;const root=t.content.querySelector('.detail105');if(!root)return html;const r=r105();if(ui106.detailId!==r.id){ui106.detailId=r.id;ui106.detailTab='summary'}const hero=root.querySelector('.detail-hero105');if(r.cover?.url){const backdrop=document.createElement('img');backdrop.className='hero-backdrop106';backdrop.src=r.cover.url;backdrop.alt='';hero.prepend(backdrop)}hero.classList.add('release-hero106');const nav=document.createElement('nav');nav.className='tabs detail-tabs106';nav.dataset.switchKey105='release-detail106';nav.setAttribute('aria-label',L105('Detail rilisan','Release detail'));nav.innerHTML=[['summary','Ringkasan','Overview'],['tracks','Lagu','Tracks'],['distribution','Distribusi','Distribution'],['history','Riwayat','History']].map(([id,a,b])=>b106(L105(a,b),'detail-tab',id,ui106.detailTab===id?'active':'text')).join('');hero.after(nav);
 const bodies={};for(const tab of ['summary','tracks','distribution','history']){const el=document.createElement('div');el.className='detail-tabbody106';el.dataset.detailSection=tab;el.hidden=ui106.detailTab!==tab;bodies[tab]=el;root.append(el)}
 const columns=root.querySelector('.detail-columns105');if(columns){const trackPanel=columns.querySelector(':scope > section'),aside=columns.querySelector('aside');if(trackPanel)bodies.tracks.append(trackPanel);if(aside)bodies.distribution.append(aside);columns.remove()}
 for(const el of [...root.children]){if(Object.values(bodies).includes(el)||el===hero||el===nav||el.matches('button'))continue;if(el.matches('details')){el.open=true;bodies.history.append(el)}else if(el.classList.contains('artist-review105'))bodies.tracks.prepend(el);else bodies.summary.append(el)}
 const links=r.songs.filter(s=>s.link);bodies.distribution.insertAdjacentHTML('beforeend',`<section class="panel detail-panel105"><h2>${L105('Tautan distribusi','Distribution links')}</h2>${links.length?links.map(s=>`<div class="distribution-link106"><strong>${E(s.title)}</strong><a class="btn" href="${E(s.link)}" target="_blank" rel="noopener noreferrer">${L105('Buka platform','Open platform')} ↗</a></div>`).join(''):`<p class="muted">${L105('Tautan ditampilkan setelah dicatat pada konfirmasi tayang.','Links appear once recorded during live confirmation.')}</p>`}</section>`);return t.innerHTML};
async function playRelease106(id){const r=allowed106(id),track=r&&audioTrack106(r);if(!track)return;const blob=await mediaStore105('readonly',track.audio.key).catch(()=>null);if(!blob){toast(L105('Audio belum tersedia pada perangkat ini.','Audio is not available on this device.'));return}stopPlayer106();const url=URL.createObjectURL(blob);ui106.player={url,role:ten.role,member:ten.member};document.body.insertAdjacentHTML('beforeend',`<aside id="catalogue-player106" class="catalogue-player106" aria-label="${L105('Pratinjau audio','Audio preview')}">${art105(r)}<div><strong>${E(track.title||r.title)}</strong><small>${E(r.artist||'')}</small></div><audio controls src="${url}"></audio>${b106('×','stop','','icon-close106')}</aside>`);document.querySelector('#catalogue-player106 audio').play().catch(()=>{})}
function stopPlayer106(){document.querySelector('#catalogue-player106')?.remove();if(ui106.player)URL.revokeObjectURL(ui106.player.url);ui106.player=null}

