function sampleCover106(title,index){const palettes=[['#315870','#dfad88'],['#383f59','#cd9392'],['#316b6d','#c6d5a0'],['#836244','#d4c08d'],['#522e54','#b5829d']],[ink,light]=palettes[index%palettes.length];return 'data:image/svg+xml,'+encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 600"><defs><linearGradient id="sky" x2=".8" y2="1"><stop stop-color="${ink}"/><stop offset="1" stop-color="${light}"/></linearGradient></defs><path fill="url(#sky)" d="M0 0h600v600H0z"/><circle cx="${140+index*55%280}" cy="210" r="145" fill="${light}" opacity=".65"/><path d="M0 450 Q150 ${230+index*20} 320 450 T650 410 V600 H0" fill="${ink}"/><path d="M0 530 Q250 360 600 490 V600 H0" fill="#132737" opacity=".5"/><text x="40" y="65" fill="#fff" font-family="sans-serif" font-size="13" letter-spacing="5">NARA SENJA</text><text x="40" y="510" fill="#fff" font-family="sans-serif" font-size="29">${E(title)}</text><text x="40" y="548" fill="#ffffff99" font-family="sans-serif" font-size="11" letter-spacing="3">RILIS MUSIK · STUDIO</text></svg>`)}
